# Node has built-in zlib but not ZIP. Let's parse the ZIP manually in Node.
node << 'EOF'
const fs = require('fs');
const zlib = require('zlib');

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers (PK\x03\x04) and extract word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) !== 0x04034b50) break; // local file header signature

  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const fnLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fileName = buf.slice(offset + 30, offset + 30 + fnLen).toString('utf8');
  const dataStart = offset + 30 + fnLen + extraLen;
  const dataEnd = dataStart + compSize;

  if (fileName === 'word/document.xml') {
    let xml;
    if (compMethod === 8) {
      xml = zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString('utf8');
    } else {
      xml = buf.slice(dataStart, dataEnd).toString('utf8');
    }

    // Extract text from paragraphs
    const parts = xml.split(/<\/w:p>/);
    for (const part of parts) {
      let line = '';
      const tRe = /<w:t[^>]*?>([^<]*)<\/w:t>/g;
      let m;
      while ((m = tRe.exec(part)) !== null) {
        line += m[1];
      }
      console.log(line);
    }
    process.exit(0);
  }

  offset = dataEnd;
}

console.error('word/document.xml not found in archive');
process.exit(1);
EOF

node << 'SCRIPT'
const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Step 1: Extract text lines from .docx ---
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');
let xmlContent = null;
let offset = 0;
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) !== 0x04034b50) break;
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const fnLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fileName = buf.slice(offset + 30, offset + 30 + fnLen).toString('utf8');
  const dataStart = offset + 30 + fnLen + extraLen;
  const dataEnd = dataStart + compSize;
  if (fileName === 'word/document.xml') {
    xmlContent = compMethod === 8
      ? zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString('utf8')
      : buf.slice(dataStart, dataEnd).toString('utf8');
    break;
  }
  offset = dataEnd;
}

if (!xmlContent) { console.error('document.xml not found'); process.exit(1); }

// Parse paragraphs with style info
const paragraphs = [];
const pParts = xmlContent.split(/<w:p[\s>]/);
pParts.shift(); // discard before first <w:p>

for (const part of pParts) {
  // Check for heading style
  const styleMatch = part.match(/<w:pStyle\s+w:val="([^"]+)"/);
  const style = styleMatch ? styleMatch[1] : 'normal';

  // Check for bold
  const hasBold = /<w:b[\s/>]/.test(part) || /Heading/.test(style);

  let line = '';
  const tRe = /<w:t[^>]*?>([^<]*)<\/w:t>/g;
  let m;
  while ((m = tRe.exec(part)) !== null) {
    line += m[1];
  }
  paragraphs.push({ text: line, style, bold: hasBold });
}

// --- Step 2: Generate PDF ---
const doc = new PDFDocument({ margin: 50 });
const outPath = '/workspace/testbed/docs/customer_report.pdf';
const stream = fs.createWriteStream(outPath);
doc.pipe(stream);

for (const para of paragraphs) {
  if (para.style.includes('Title') || para.style === 'Heading1') {
    doc.fontSize(20).font('Helvetica-Bold').text(para.text, { paragraphGap: 8 });
  } else if (para.style === 'Heading2') {
    doc.fontSize(16).font('Helvetica-Bold').text(para.text, { paragraphGap: 6 });
  } else if (para.style === 'Heading3') {
    doc.fontSize(13).font('Helvetica-Bold').text(para.text, { paragraphGap: 4 });
  } else if (para.text === '') {
    doc.fontSize(11).text(' ', { paragraphGap: 2 });
  } else {
    const font = para.bold ? 'Helvetica-Bold' : 'Helvetica';
    doc.fontSize(11).font(font).text(para.text, { paragraphGap: 2 });
  }
}

doc.end();
stream.on('finish', () => {
  const stats = fs.statSync(outPath);
  console.log('PDF created: ' + outPath + ' (' + (stats.size / 1024).toFixed(1) + ' KB)');
});
SCRIPT
